package com.moonsworth.lunar.client.render.shader;

public class ShaderSource {
   public static String field1 = "LUNAR-SHADER-DEFINITION-MARKER\n\nvoid main(){\n    vec4 outPos = vec4(POS.xy, 0.0, 1.0);\n    outPos -= 0.5;\n    outPos *= 2.0;\n\n    gl_Position = vec4(outPos.xy, 0.2, 1.0);\n    uv = vec2(POS.x, POS.y);\n}\n";
   public static String field2 = "LUNAR-SHADER-DEFINITION-MARKER\n\nvoid main(){\n    vec4 outPos = vec4(UV.xy, 0.0, 1.0);\n    outPos -= 0.5;\n    outPos *= 2.0;\n\n    gl_Position = vec4(outPos.xy, 0.2, 1.0);\n    uv = vec2(UV.x, UV.y);\n\n    #ifdef LEGACY_MODELVIEW_RESIZE\n        mat4 ModelView = mat4(MODEL_VIEW_MAT);\n        vec3 normalMul = vec3(1.0);\n        if (LEGACY_MODELVIEW_RESIZE.x > 0.0) {\n            mat4 N = mat4(\n                vec4(1.0 / LEGACY_MODELVIEW_RESIZE.x, 0.0, 0.0, 0.0),\n                vec4(0.0, -1.0 / LEGACY_MODELVIEW_RESIZE.y, 0.0, 0.0),\n                vec4(0.0, 0.0, 1.0, 0.0),\n                vec4(-0.5, 0.5, 0.0, 1.0)\n            );\n\n            ModelView = N * ModelView;\n            normalMul = vec3(1.0, -1.0, 1.0);\n        }\n\n        worldPos = (ModelView * vec4(POS, 1.0)).xyz;\n        normal = normalize(NORMAL_MAT * NORMAL) * normalMul;\n    #else\n        worldPos = (MODEL_VIEW_MAT * vec4(POS, 1.0)).xyz;\n        normal = normalize(NORMAL_MAT * NORMAL);\n    #endif\n}\n";
   public static String field3 = "LUNAR-SHADER-DEFINITION-MARKER\n\nvoid main(){\n    OUT_COLOR = vec4(uv.x, uv.y, 0.0, 1.0);\n}\n";
   public static String field4 = "//LUNAR-SHADER-DEFINITION-MARKER\n\n#define NONE 0.1\n#define SET 0.8\n\nvoid main() {\n    int side = 0;\n    float x = uv.x * 22.0;\n    float y = uv.y * 17.0;\n\n    if (x <= 1.0) {\n        side = 0;\n    } else if (x <= 11 && y <= 1.0) {\n        side = 1;\n    } else if (x <= 11) {\n        side = 2;\n    } else if (x <= 12 && y > 1.0) {\n        side = 3;\n    } else if (y <= 1.0) {\n        side = 4;\n    } else {\n        side = 5;\n    }\n\n    vec3 clr = vec3(SET);\n    switch (side) {\n        case 0:\n            clr = vec3(SET, NONE, NONE);\n            break;\n        case 1:\n            clr = vec3(SET, SET, NONE);\n            break;\n        case 2:\n            clr = vec3(NONE, SET, NONE);\n            break;\n        case 3:\n            clr = vec3(NONE, SET, SET);\n            break;\n        case 4:\n            clr = vec3(NONE, NONE, SET);\n            break;\n        case 5:\n            clr = vec3(SET, NONE, SET);\n            break;\n    }\n\n    OUT_COLOR = vec4(clr, 1.);\n}\n";
}
